window.RP_SESSION={"id":"S-a2fdbae703bf","messages":[{"id":"RP-0296364","time":"2026-09-23T08:56:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"이른 아침.","characters":["P-92738ae601c0"]},{"id":"RP-0296365","time":"2026-09-23T08:58:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"기지개와 함께 길드 건물을 걷던 머챈트는...\n\n-뿌작...\n\n\" 에, 에엥? 뿌-작? \"\n\n자신의 발 밑에 느껴지는 물컹~끈적한 감촉에 시선을 내려 발 밑을 봅니다.\n\n\" ... 에...엥? \"","characters":["P-92738ae601c0"]},{"id":"RP-0296366","time":"2026-09-23T08:58:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-92738ae601c0"]},{"id":"RP-0296367","time":"2026-09-23T09:09:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"머챈트는 인형을 들어봅니다.\n\n\" 으엑, 물컹거려. 뭐...야 이거? \"","characters":["P-92738ae601c0"]},{"id":"RP-0296368","time":"2026-09-23T09:15:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"어라, 머챈트씨? 안녕하세요! 좋은 아침이네요.\"\n\n에스텔은 땀을 닦으며 길드 로비로 들어왔습니다. 봉사를 다녀왔거든요.\n\n\"어라, 그건 뭔가요? 으음, 방에서 모카씨가 갖고놀던 거랑 비슷한 것 같은데.\"","characters":["P-b522cca806d0"]},{"id":"RP-0296369","time":"2026-09-23T09:17:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" ... 그래보이네 -- \"","characters":["P-92738ae601c0"]},{"id":"RP-0296370","time":"2026-09-23T09:17:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-92738ae601c0"]},{"id":"RP-0296371","time":"2026-09-23T09:17:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"노카요...?\"","characters":["P-b522cca806d0"]},{"id":"RP-0296372","time":"2026-09-23T09:18:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"험, 모카씨한테 글씨 쓰는 걸 알려드려야 하나...?\"","characters":["P-b522cca806d0"]},{"id":"RP-0296373","time":"2026-09-23T09:18:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 이게 가지고 놀았으면 제대로 가져 가든가 어디 치워두던가 해야지-!!\"","characters":["P-92738ae601c0"]},{"id":"RP-0296374","time":"2026-09-23T09:18:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-92738ae601c0"]},{"id":"RP-0296375","time":"2026-09-23T09:19:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"아하하, 죄송해요. 제가 대신 사과드릴게요. 같은 방을 쓰는 제가 제대로 돌보지 못한 것도 있으니까요...\"\n\n에스텔은 쓴웃음을 지으며, 인형을 건내받아 품에 안았습니다. 찐득...한 것이 조금 배어나와 옷에 묻은 것 같아요.","characters":["P-b522cca806d0"]},{"id":"RP-0296376","time":"2026-09-23T09:22:00+09:00","room":"RP","name":"모카","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"슬쩍... 계단에 걸쳐 대화를 엿듣고.... 후다다닥 방으로 돌아가 자는 척하기로 합니다","characters":["P-f400f584340f"]},{"id":"RP-0296377","time":"2026-09-23T09:24:00+09:00","room":"RP","name":"모카","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-f400f584340f"]},{"id":"RP-0296378","time":"2026-09-23T09:25:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-b522cca806d0"]},{"id":"RP-0296379","time":"2026-09-23T09:25:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'에스텔 벨라시타'의 민첩 판정 :\n[9] + [-1] = [8]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-0296380","time":"2026-09-23T09:25:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"?\"\n\n에스텔은 그 탑탑탑탑, 하는 발 소리를 들은건지, 계단쪽으로 시선을 옮깁니다.","characters":["P-b522cca806d0"]},{"id":"RP-0296381","time":"2026-09-23T09:26:00+09:00","room":"RP","name":"모카","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-f400f584340f"]},{"id":"RP-0296382","time":"2026-09-23T09:26:00+09:00","room":"RP","name":"모카","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"땀 삐질삐질 흘리며 에스탤 바라봅니다","characters":["P-f400f584340f"]},{"id":"RP-0296383","time":"2026-09-23T09:26:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"모카씨? 거기서 그러지 말고 이리오세요. 안 혼낼게요.\"","characters":["P-b522cca806d0"]},{"id":"RP-0296384","time":"2026-09-23T09:26:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"나는.","characters":["P-b522cca806d0"]},{"id":"RP-0296385","time":"2026-09-23T09:26:00+09:00","room":"RP","name":"모카","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"삐져나온 꼬리 잘 잡아 숨겨서 호다닥......","characters":["P-f400f584340f"]},{"id":"RP-0296386","time":"2026-09-23T09:26:00+09:00","room":"RP","name":"모카","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"ㅎ하지만...\"","characters":["P-f400f584340f"]},{"id":"RP-0296387","time":"2026-09-23T09:27:00+09:00","room":"RP","name":"모카","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"모카 어제 깜빡한거야...!\"","characters":["P-f400f584340f"]},{"id":"RP-0296388","time":"2026-09-23T09:27:00+09:00","room":"RP","name":"모카","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"치울거였어...!\"","characters":["P-f400f584340f"]},{"id":"RP-0296389","time":"2026-09-23T09:27:00+09:00","room":"RP","name":"모카","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"...요...!\"","characters":["P-f400f584340f"]},{"id":"RP-0296390","time":"2026-09-23T09:27:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"에스텔은 모카의 손을 조심히 잡고, 데리고 내려옵니다.\n\n\"괜찮아요. 그럴 수 있죠. 아하하...다음부터 정리 잘 하면 되는거에요.\"","characters":["P-b522cca806d0"]},{"id":"RP-0296391","time":"2026-09-23T09:27:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 깜빡할게 따로있지! 심지어 계단 앞에다가! 어-! 너 모카 누가 밟고 넘어지기라도 하면 어쩌려고 그래!? \"","characters":["P-92738ae601c0"]},{"id":"RP-0296392","time":"2026-09-23T09:28:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 저번에도 어! 네가 아도니스가 들고다니던 상어 인형 그거 갖고싶다고 떼쓰다가 안되니까 만들어보겠다고 여기저기 어질러놓고! \"","characters":["P-92738ae601c0"]},{"id":"RP-0296393","time":"2026-09-23T09:29:00+09:00","room":"RP","name":"모카","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"...돌고랜뎅....\"","characters":["P-f400f584340f"]},{"id":"RP-0296394","time":"2026-09-23T09:29:00+09:00","room":"RP","name":"모카","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-f400f584340f"]},{"id":"RP-0296395","time":"2026-09-23T09:30:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"모카씨.\"\n\n에스텔의 등을 약하게 툭 쳤습니다.\n대충 말대꾸하지 말라는 뜻.","characters":["P-b522cca806d0"]},{"id":"RP-0296396","time":"2026-09-23T09:30:00+09:00","room":"RP","name":"모카","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"웅...\"","characters":["P-f400f584340f"]},{"id":"RP-0296397","time":"2026-09-23T09:31:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 상어든 돌고래든! \"(분노)","characters":["P-92738ae601c0"]},{"id":"RP-0296398","time":"2026-09-23T09:32:00+09:00","room":"RP","name":"모카","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"...미아네 머챈트 언니이...\"","characters":["P-f400f584340f"]},{"id":"RP-0296399","time":"2026-09-23T09:32:00+09:00","room":"RP","name":"모카","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\".....요?\"","characters":["P-f400f584340f"]},{"id":"RP-0296400","time":"2026-09-23T09:33:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 네 물건은 이제 네가 알아서 치워! 이제 바닥에 버려두고 간 장난감 보일때마다 다 버릴거야 -- \"","characters":["P-92738ae601c0"]},{"id":"RP-0296401","time":"2026-09-23T09:33:00+09:00","room":"RP","name":"모카","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"안돼애!!\"","characters":["P-f400f584340f"]},{"id":"RP-0296402","time":"2026-09-23T09:34:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"으음. 뒤에다가 요만 붙인다고 다 존대가 되는건 아닌데요...\n\n에스텔은 모카에게 알려줄 게 하나 더 생겼다고 머릿속에 새겨두고는 무릎을 굽혀(비록 한쪽 밖에 없지만.) 모카와 눈높이를 맞췄습니다.","characters":["P-b522cca806d0"]},{"id":"RP-0296403","time":"2026-09-23T09:35:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"모카씨. 가지고 놀았으면 확실히 치워두는 게 좋아요. 길드 건물은 다른 분들도 사용하시는 곳이잖아요? 계단에서 내려오다가 누군가 다쳤을 수도 있어요.\"\n\n음...\n\n\"그래도, 으음...정리가 필요하시면 제가 도와드릴게요. 같이 하나씩 해볼까요?\"","characters":["P-b522cca806d0"]},{"id":"RP-0296404","time":"2026-09-23T09:35:00+09:00","room":"RP","name":"모카","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"알았어어...\"","characters":["P-f400f584340f"]},{"id":"RP-0296405","time":"2026-09-23T09:36:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"좋아요. 고마워요.\"\n\n에스텔은 베시시 웃으며 모카의 머리를 헝클어트리듯 쓰다듬었습니다.","characters":["P-b522cca806d0"]},{"id":"RP-0296406","time":"2026-09-23T09:36:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"머챈트씨도, 너무 뭐라하진 말아주세요. 모카씨도 노력하고 있으니까요. 조금만 더 기다려 주실 수 있나요?\"","characters":["P-b522cca806d0"]},{"id":"RP-0296407","time":"2026-09-23T09:38:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 알긴 쥐뿔이-! \"\n\n딱콩!\n\n머챈트는 모카에게 꿀밤을 선사했습니다.\n\n\" 코나 닦아 지지배야, 가서 손 씻고! \"","characters":["P-92738ae601c0"]},{"id":"RP-0296408","time":"2026-09-23T09:38:00+09:00","room":"RP","name":"모카","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"훌쩍","characters":["P-f400f584340f"]},{"id":"RP-0296409","time":"2026-09-23T09:38:00+09:00","room":"RP","name":"모카","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"알아써어..\"","characters":["P-f400f584340f"]},{"id":"RP-0296410","time":"2026-09-23T09:38:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"요.\"","characters":["P-b522cca806d0"]},{"id":"RP-0296411","time":"2026-09-23T09:38:00+09:00","room":"RP","name":"모카","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"요...\"","characters":["P-f400f584340f"]},{"id":"RP-0296412","time":"2026-09-23T09:38:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"잘했어요.\"","characters":["P-b522cca806d0"]},{"id":"RP-0296413","time":"2026-09-23T09:39:00+09:00","room":"RP","name":"모카","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"곰탱이 옆구리에 끼고 뚜벅뚜벅...","characters":["P-f400f584340f"]},{"id":"RP-0296414","time":"2026-09-23T09:39:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 너 또 입으로 씻는 소리만 흉내내면 가만 안둔다-!! 다 씻으면 검사할거야-! \"\n\n머챈트는 멀어져가는 모카에게 소리쳤습니다.\n\n그리곤 에스텔을 쳐다보며 인상을 찌푸렸습니다.\n\n\" 이봐요 에스텔. 대체 왜 그래요? 어디 문제있나요? \"","characters":["P-92738ae601c0"]},{"id":"RP-0296415","time":"2026-09-23T09:40:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"네? 어...혹시 제가 문제 될만한 일을 했나요...?\"\n\n에스텔은 고개를 갸웃거렸습니다.\n심히, 걱정스러운 표정이네요.","characters":["P-b522cca806d0"]},{"id":"RP-0296416","time":"2026-09-23T09:41:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 지금 난 나쁜년이고 그쪽은 착한년 하겠단지는 모르겠는데, 관계는 책임이에요. 케잌 위에 얹혀진 딸기 조각만 떼먹는게 아니라요. \"","characters":["P-92738ae601c0"]},{"id":"RP-0296417","time":"2026-09-23T09:41:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"윽. 죄송해요. 그런 의도는 아니었어요.\"","characters":["P-b522cca806d0"]},{"id":"RP-0296418","time":"2026-09-23T09:43:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"머챈트는 에스텔의 반응에 작게 숨을 내쉬었습니다.\n\n \" 미안해요. 갑자기 히스테릴 부려서. 근데 쟤 한 두번이 아녜요. 나땐 어른 무서운 줄 알면서 자랐다구요. \"","characters":["P-92738ae601c0"]},{"id":"RP-0296419","time":"2026-09-23T09:47:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"앗, 음...아니에요. 충분히 그럴 수 있었다고 생각해요.\"\n\n에스텔은 부모님이나 선생님에게 혼난 10대 청소년 마냥 두 손을 모으곤 안절부절 손가락을 매만졌습니다.\n\n그러다가 입을 열기를,\n\n\"모카씨는...\"\n\n음. 아무래도요. 그녀는 주위를 좀 가볍게 여기고 스스로의 일에 몰두하는 경향이 크죠.\n\n에스텔은 그저 어릴때 보호자를 잃으셔서 그런 걸 거에요...라고 말하려다가. 멈칫했습니다.\n\n그건, 음. 꽤 실례되는 말로 들릴 수 있으니까요.\n\n\"역시 조금 혼을 내야하나요...?\"","characters":["P-b522cca806d0"]},{"id":"RP-0296420","time":"2026-09-23T10:08:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"어쩔 줄 몰라하는 에스텔의 자세와 달리, 머챈트는 자신의 허리춤에 한 손을 얹은 뒤 얘기를 이어갔습니다.\n\n\" 조금이 아니라 계속, 계속 그래야죠. 계~~~속. 잘못된건 잘못됐다, 잘한 건 잘했다. 애들은 말 안해주면 뭐가 잘됐고 잘못됐는지 몰라요. 그냥 막 그냥 왜? 왜? 왜? 왜요? 왜? 하면서 꽥꽥꽥꽥 🦆 배고픈 오리마냥 달려든다구.\n\n마냥 아이 귀엽다, 아이 예쁘다 해주면 나중에 힘들어져요. 우리가 아니라 쟤가. \"\n\n그리곤 잠시 숨이 찬 듯 말을 멈추고 모카가 걸어간 길목(복도)를 쳐다봤습니다.\n\n뚝뚝뚝 떨어뜨린 정체 모를 끈적이들.\n\n\" ... 우리가 평생 데리고 책임져줄 게 아니라면, 기억이라도 남겨줘야죠. 쟤한테 도움이 될 수 있는. 혼자 남겨지더라도 헤쳐나갈 수 있는 지혜를요. \"","characters":["P-92738ae601c0"]},{"id":"RP-0296421","time":"2026-09-23T10:14:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"그 말에 에스텔은 모카가 사라진 길을 바라보았습니다.\n\n그녀의 뒷모습은 처량하고 쓸쓸해보입니다. 그 이유가 단지 '누군가에게 혼나서'는 아닐지도 모르겠네요.\n\n\"...\"\n\n좋아요. 에스텔은 심호흡했습니다.\n\n\"고마워요. 머챈트씨. 제가 잘못 생각했었나봐요.\"\n\n세상만사 거칠고 단단하게만 넘어갈 수 없듯. 모든 일에 유하게만 대처 할 수는 없는거겠죠. 지금 같은 상황에서요.\n\n여태 그래왔었죠. 유함과 친절함만이 최선의 방법이라고 믿고, 단호하게 행동하는 것을 선택지 밖으로 밀어냈었어요.\n\n\"아하하. 방에 돌아가면 제가 한 번 따끔해게 혼내볼게요. 으음- 잘 할 수 있을지는 모르겠지만요.\"","characters":["P-b522cca806d0"]},{"id":"RP-0296422","time":"2026-09-23T10:15:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 그냥 둬요. 한 번 화냈으면 됐어요. 거기서부터 같은 얘기로 또 화내면 그건 감정풀이야. 아, 혹시 좀 갈색 도는 천이나 그런거 없어요? \"","characters":["P-92738ae601c0"]},{"id":"RP-0296423","time":"2026-09-23T10:16:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"알았어요. 조언 고마워요. 그건 그렇고, 갈색 천이요? 한 번 찾아볼게요. 어디 쓰실 예정인가요?\"","characters":["P-b522cca806d0"]},{"id":"RP-0296424","time":"2026-09-23T10:18:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 다 새잖아요. \"\n\n머챈트는 바닥에 떨어진 끈끈이를 가르켰습니다.\n\n시간이 지나며 딱딱히 굳은 끈적이들.\n\n\" 적어도 놀거면 제대로 된 걸 만들어주려구요. 저게 뭔진 모르겠는데, 애들 호기심이야 도통 어디까지 뻗어갈지 모르니까 혹시라도 먹을까봐서. \"","characters":["P-92738ae601c0"]},{"id":"RP-0296425","time":"2026-09-23T10:20:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"...! 정말요? 모카씨가 기뻐할거에요.\"\n\n에스텔은 싱글싱글 웃으며 어딘가로 향했다가, 이내 몇가지 천을 들고 돌아오네요.\n\n\"여기요. 어...근데 이건 음, 가져오지 말걸 그랬으려나요...? 라르손씨가 주신건데.\"\n\n뭔가...뭔가 이상한 냄새가 나는 천 하나가 섞여있습니다. 뭐. 약품 냄새겠죠. 이 글을 보고있는 당신. 편견에 휩싸이지 마!","characters":["P-b522cca806d0"]},{"id":"RP-0296426","time":"2026-09-23T10:26:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"머챈트는 적당한 색감의 천을 하나 받아들었습니다.\n\n베어와 비슷한 색감의 천.\n\n\" 이 정도면... 비슷하겠네요. 고마워요 ㅎ \"","characters":["P-92738ae601c0"]},{"id":"RP-0296427","time":"2026-09-23T10:31:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"천만에요. 혹시 저도 도울 게 있을까요? 모카씨에게 선물할거라면 부디 돕고싶어요.\"","characters":["P-b522cca806d0"]},{"id":"RP-0296428","time":"2026-09-23T10:52:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 음- 글쎄요, 아. 맞다. 요새 마레 표정이 영 안좋아보이던데요? \"","characters":["P-92738ae601c0"]},{"id":"RP-0296429","time":"2026-09-23T10:55:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"마리우스씨요?\"","characters":["P-b522cca806d0"]},{"id":"RP-0296430","time":"2026-09-23T10:55:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"시점이 언제지 여기...","characters":["P-b522cca806d0"]},{"id":"RP-0296431","time":"2026-09-23T10:59:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"으음...자세한 사정은 잘 모르겠지만, 최근 좀 일이 있는 모양이에요. 임무에서 돌아오시면 한 번 찾아뵈어 보려고요.\"","characters":["P-b522cca806d0"]},{"id":"RP-0296432","time":"2026-09-23T12:10:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 아님 담번에 여자들끼리 밥 한 번 먹어요. \"","characters":["P-92738ae601c0"]},{"id":"RP-0296433","time":"2026-09-23T12:10:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 서로 얼굴도 알 겸요. \"","characters":["P-92738ae601c0"]},{"id":"RP-0296434","time":"2026-09-23T12:43:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"아하하, 좋아요. 흐음- 한번, 주관해볼까요?\"","characters":["P-b522cca806d0"]},{"id":"RP-0296435","time":"2026-09-23T12:48:00+09:00","room":"RP","name":"에스텔","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-b522cca806d0"]},{"id":"RP-0296436","time":"2026-09-23T12:48:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
